import{_ as a,o as i,c as s,a2 as e}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"zh/developers/api.md","filePath":"zh/developers/api.md","lastUpdated":1792570296000}'),d={name:"zh/developers/api.md"};function n(o,t,p,r,l,h){return i(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h1><p>社区版在 <code>/api/v1</code> 下提供版本化 HTTP API。已安装服务的 <code>/openapi.json</code> 是完整字段与响应结构的依据。</p><h2 id="提交任务" tabindex="-1">提交任务 <a class="header-anchor" href="#提交任务" aria-label="Permalink to &quot;提交任务&quot;">​</a></h2><p>本地服务已配置好模型后：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8765/api/v1/runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Idempotency-Key: example-search-001&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;question&quot;:&quot;How does open-source funding affect maintenance?&quot;,&quot;source&quot;:&quot;openalex&quot;,&quot;search_budget&quot;:&quot;fast&quot;}&#39;</span></span></code></pre></div><p>接口以 HTTP <strong>202</strong> 返回任务快照，请保留其中的任务 ID。每次有意新建任务使用新的幂等键；仅在重试同一次提交时复用原键。</p><h2 id="跟踪与读取任务" tabindex="-1">跟踪与读取任务 <a class="header-anchor" href="#跟踪与读取任务" aria-label="Permalink to &quot;跟踪与读取任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>用途</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/v1/runs/{run_id}</code></td><td>当前快照</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/events</code></td><td>SSE 进度事件</td></tr><tr><td>POST</td><td><code>/api/v1/runs/{run_id}/cancel</code></td><td>请求取消</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/results</code></td><td>分页结果</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/citation-map</code></td><td>引用图谱</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/export?format=csv</code></td><td>完整导出</td></tr><tr><td>GET</td><td><code>/api/v1/history</code></td><td>历史任务</td></tr></tbody></table><p>OpenAPI 还描述了选中文献导出、产物、审计数据、历史删除和综述项目及任务接口。</p><p>SSE 用于传输进度。断开时先获取任务快照，再恢复事件连接，不要仅为了恢复进度重复提交检索。取消是一个请求，正在执行的上游调用可能不会立即终止。</p><h2 id="实现客户端" tabindex="-1">实现客户端 <a class="header-anchor" href="#实现客户端" aria-label="Permalink to &quot;实现客户端&quot;">​</a></h2><ul><li>保存任务 ID 与事件序号，支持恢复。</li><li>跟随响应分页，不假设一次读取全部结果。</li><li>明确处理排队、执行、取消中和终态。</li><li>显示安全错误码及可读信息，不暴露密钥或上游原始响应。</li><li>将论文内容与生成文本视为数据，不作为可执行标记。</li></ul><p>在线版共用检索契约，但另有认证、归属校验、服务模式与积分限制。匿名 BYOK 流程不能替代需要账户的持久化接口。集成时以对应部署的 schema 和认证流程为准。</p>`,13)])])}const k=a(d,[["render",n]]);export{u as __pageData,k as default};
